package main

import "fmt"

func main() {
	scores := []int{64, 70, 82, 88, 95}
	fmt.Println("low two:", scores[:2])
	fmt.Println("top three:", scores[len(scores)-3:])
	fmt.Println("middle:", scores[1:4])

	scores = scores[:len(scores)-1]
	extra := []int{100, 99}
	scores = append(scores, extra...)
	fmt.Println("joined:", scores)
}

