practice.solution:
package main

import (
	"fmt"
	"sort"
)

func main() {
	laps := []int{61, 58, 64, 59}
	weights := []float64{2.5, 0.75, 1.5}
	cities := []string{"rome", "Oslo", "lima"}

	sort.Ints(laps)
	sort.Float64s(weights)
	sort.Strings(cities)

	fmt.Println(laps)
	fmt.Println(weights)
	fmt.Println(cities)
	fmt.Printf("lightest: %.2f\n", weights[0])
	fmt.Printf("heaviest: %.2f\n", weights[len(weights)-1])
}
